provider "aws" {
  region = "us-east-1"
}

resource "aws_cloudwatch_log_group" "aws_route53_example_com" {
  name = "aws_route53_example_com"
}

resource "aws_cloudwatch_log_resource_policy" "route53_query_logging_policy" {
  name = "route53_query_logging_policy"
  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = aws_cloudwatch_log_group.aws_route53_example_com.arn
      }
    ]
  })
}

resource "aws_route53_zone" "primary" {
  name = "primary"
}

resource "aws_cloudwatch_log_stream" "aws_route53_example_com_query_logs" {
  name = "aws_route53_example_com_query_logs"
  depends_on = [aws_cloudwatch_log_group.aws_route53_example_com]
}

resource "aws_route53_query_logging_config" "route53_query_logging_config" {
  zone_id = aws_route53_zone.primary.id
