resource "aws_autoscaling_group" "my_api_app_asg" {
  name               = "my_api_app_asg"
  launch_configuration_name = aws_launch_configuration.my_api_app_lc.name
  min_size           = 1
  max_size           = 3
  desired_capacity   = 2

  vpc_zone_identifier = ["subnet-12345678", "subnet-87654321"]

  health_check_type = "EC2"
  health_check_grace_period = 300

  tag {
    key   = "Name"
    value = "my_api_app_asg"
    propagate_at_launch = true
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_launch_configuration" "my_api_app_lc" {
  name_prefix = "my_api_app_lc"
  image_id     = "ami-0abcdef1234567890"
  instance_type = "t2.micro"

  user_data = <<-EOF
    #!/bin/bash
    yum update -y
    yum install -y httpd
    systemctl start httpd
    systemctl enable httpd
  EOF

  security_groups = ["sg-12345678"]
}

