  name                = "my_api_app_env"
  application         = aws_elastic_beanstalk_application.my_api_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.0.0 running Python 3.8"
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile.name

  auto_scaling_groups = [aws_autoscaling_group.my_api_app_asg.name]

  load_balancer_names = ["my_api_app_lb"]

  tags = {
    Name = "my_api_app_env"
  }
}

resource "aws_elastic_load_balancer" "my_api_app_lb" {
  name               = "my_api_app_lb"
  subnets            = ["subnet-12345678", "subnet-87654321"]
  security_groups     = ["sg-12345678"]
  internal           = false
  cross_zone_load_balancing = true

  listener {
    instance_port    = 80
    instance_protocol = "HTTP"
    lb_port          = 80
    lb_protocol      = "HTTP"
  }
}
