            "value"    = "size"
          }
        ]
      }
    }
    {
      name          = "PizzaToppingSlot"
      description = "The toppings on the pizza"
      slot_values = {
        "values" = [
          {
            "synonyms" = ["pepperoni", "mushrooms", "onions"]
            "value"    = "toppings"
          }
        ]
      }
    }
  ]
  intents = [
    {
      intent_name = "PizzaOrderIntent"
      slots       = [
        {
          name          = "PizzaSizeSlot"
          slot_type_name = "PizzaSizeSlot"
        }
        {
          name          = "PizzaToppingSlot"
          slot_type_name = "PizzaToppingSlot"
        }
      ]
      sample utterances = [
        "I want a large pizza with pepperoni and mushrooms.",
