}

resource "aws_opensearch_domain_endpoint_options" "opensearch_domain_endpoint_options" {
  domain_name = aws_opensearch_domain.opensearch_domain.domain_name
  enforce_https = true
}

resource "aws_opensearch_domain_policy" "opensearch_domain_policy" {
  domain_name = aws_opensearch_domain.opensearch_domain.domain_name
  policy = var.opensearch_domain_access_policies
}

resource "aws_opensearch_domain_service_role" "opensearch_domain_service_role" {
  domain_name = aws_opensearch_domain.opensearch_domain.domain_name
}

resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name = "kinesis_firehose_delivery_stream"

  destination {
    opensearch {
      domain_arn = aws_opensearch_domain.opensearch_domain.arn
      index_name = "my-index"
      type = "opensearch"
      role_arn = aws_opensearch_domain_service_role.opensearch_domain_service_role.arn
      buffering_interval_in_seconds = 60
      buffering_size_in_megabytes = 5
      compression_format = "GZIP"
      retry_options {
        duration_in_seconds = 60
        maximum_retry_attempts = 3
      }
      s3_backup_mode = "Enabled"
      s3_configuration {
        bucket_arn = aws_s3_bucket.s3_bucket.arn
        role_arn = aws_iam_role.kinesis_firehose_role.arn
        prefix = "firehose/"
      }
      processing_configuration {
        enabled = true
        processors {
          type = "Lambda"
          parameters {
            parameter_name = "LambdaArn"
            parameter_value = aws_lambda_function.lambda_function.arn
          }
        }
      }
    }
  }
}

resource "aws_s3_bucket" "s3_bucket" {
  bucket = "my-kinesis-firehose-bucket"
}

resource "aws_iam_role" "kinesis_firehose_role" {
  name = "kinesis_firehose_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_lambda_function" "lambda_function" {
  filename      = "lambda_function.zip"
  function_name = "my-lambda-function"
  handler       = "index.handler"
  runtime       = "python3.8"

  role = aws_iam_role.kinesis_firehose_role.arn

  source_code_hash = filebase64sha256("lambda_function.zip")
}
