```hcl
provider "aws" {
  region = "us-west-2" # Example region, adjust as needed
}

variable "cluster_name" {
  default = "example"
}

resource "aws_eks_cluster" "example" {
  name     = var.cluster_name
  role_arn = aws_iam_role.example_eks_role.arn

  vpc_config {
    subnet_ids = [aws_subnet.example.id]
  }

  depends_on = [aws_iam_role_policy_attachment.example_eks_role_policy_attachment]
}

resource "aws_iam_role" "example_eks_role" {
  name = "${var.cluster_name}_eks_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "example_eks_role_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.example_eks_role.name
}

resource "aws_eks_oidc_identity_provider" "example_oidc" {
  cluster_name = aws_eks_cluster.example.name
  client_id    = "your_client_id_here" # Replace with your actual client ID
  issuer_url   = "https://oidc.eks.region.amazonaws.com/id/YOUR_OIDC_PROVIDER_ID" # Replace with your actual issuer URL

  depends_on = [aws_eks_cluster.example]
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with a specific region (`us-west-2`).
- **Variables**: A variable `cluster_name` is defined with a default value of `"example"`.
- **EKS Cluster**: The `aws_eks_cluster` resource is created with the specified name and role ARN. It uses a subnet from `aws_subnet.example`.
- **IAM Role**: An IAM role `example_eks_role` is created with permissions for EKS operations.
- **IAM Role Policy Attachment**: This attaches the `AmazonEKSClusterPolicy` to the IAM role.
- **OIDC Identity Provider**: The `aws_eks_oidc_identity_provider` resource is linked to the EKS cluster using the cluster name. You need to replace `"your_client_id_here"` and `"https://oidc.eks.region.amazonaws.com/id/YOUR_OIDC_PROVIDER_ID"` with your actual client ID and issuer URL.

