  }
}

resource "aws_dynamodb_table" "terraform_lock_table" {
  name           = "terraform-lock-table-${var.environment}"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "LockID"
  attribute {
    name = "LockID"
    type = "S"
  }
}

output "s3_bucket_arn" {
  value = aws_s3_bucket.terraform_state_bucket.arn
