provider "aws" {
  region = "us-east-1"
}

variable "on_demand_instances_count" {
  default = 5
}

variable "spot_instances_count" {
  default = 4
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public_subnet" {
  vpc_id     = aws_vpc.vpc.id
  cidr_block = "10.0.0.0/24"
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private_subnet" {
  vpc_id     = aws_vpc.vpc.id
  cidr_block = "10.0.1.0/24"
}

resource "aws_launch_template" "launch_template" {
  name_prefix = "linux_2_template"

  instance_type = "t2.micro"
  image_id       = "ami-0c55b159cbfafe1f0" # Latest Amazon Linux 2 AMI ID

  user_data = <<-EOF
    #!/bin/bash
    yum update -y
    EOF

  iam_instance_profile {
    name = "ec2-instance-profile"
  }

  tags = {
    Name = "Linux 2 Instance"
  }
}

resource "aws_security_group" "sg" {
  name        = "allow_all"
  description = "Allow all inbound traffic"

  ingress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance_profile" "ec2-instance-profile" {
  name = "ec2-instance-profile"

  role = aws_iam_role.ec2-instance-role.name
}

resource "aws_iam_role" "ec2-instance-role" {
  name = "ec2-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2-instance-policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforSSM"
  role       = aws_iam_role.ec2-instance-role.name
}

resource "aws_ec2_fleet" "ec2_fleet" {
  launch_template_specification {
    launch_template_id = aws_launch_template.launch_template.id
  }

  target_capacity_specification {
    on_demand_target_capacity = var.on_demand_instances_count
    spot_target_capacity     = var.spot_instances_count
    total_target_capacity    = var.on_demand_instances_count + var.spot_instances_count
  }

  allocation_strategy = "lowest-price"

  instance_types = ["t2.micro"]

  subnet_mappings {
    subnet_id = aws_subnet.public_subnet.id
  }

  subnet_mappings {
    subnet_id = aws_subnet.private_subnet.id
  }

  iam_instance_profile {
    arn = aws_instance_profile.ec2-instance-profile.arn
  }

  network_interfaces {
    associate_public_ip_address = true
    device_index               = 0
    subnet_id                  = aws_subnet.public_subnet.id
    groups                    = [aws_security_group.sg.id]
  }

  network_interfaces {
    device_index               = 1
    subnet_id                  = aws_subnet.private_subnet.id
    groups                    = [aws_security_group.sg.id]
  }
}
