```hcl
provider "aws" {
  region = "us-east-1"  # Replace with your desired AWS region
}

variable "lambda_function_name" {
  default = "lambda_function"
}

variable "lambda_function_handler" {
  default = "lambda.js:index.handler"
}

variable "lambda_function_runtime" {
  default = "nodejs14.x"
}

variable "lambda_function_timeout" {
  default = 30
}

variable "lambda_function_memory_size" {
  default = 128
}

variable "s3_bucket_name" {
  default = "lambda-function-code-bucket"
}

resource "aws_s3_bucket" "s3_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"
}

resource "aws_s3_object" "lambda_code" {
  bucket  = aws_s3_bucket.s3_bucket.bucket
  key     = "lambda.js"
  source  = "path/to/your/lambda.js"  # Update with the path to your lambda.js file
  etag   = filemd5("path/to/your/lambda.js")  # Update with the MD5 hash of your lambda.js file
}

resource "aws_lambda_function" "lambda_function" {
  function_name = var.lambda_function_name
  handler       = var.lambda_function_handler
  runtime       = var.lambda_function_runtime
  timeout        = var.lambda_function_timeout
  memory_size    = var.lambda_function_memory_size
  role          = aws_iam_role.lambda_function_role.arn

  environment {
    variables = {
      # Add any environment variables here
    }
  }

  role_arn = aws_iam_role.lambda_function_role.arn
  s3_bucket = aws_s3_bucket.s3_bucket.bucket
  s3_key    = aws_s3_object.lambda_code.key
}

resource "aws_iam_role" "lambda_function_role" {
  name = "${var.lambda_function_name}_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_function_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_function_role.name
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the default region `us-east-1`.
- **Variables**: Variables are defined for the Lambda function name, handler, runtime, timeout, memory size, S3 bucket name, and any environment variables.
- **S3 Bucket**: An S3 bucket is created to store the Lambda function code.
- **S3 Object**: The Lambda function code file is uploaded to the S3 bucket.
- **Lambda Function**: The Lambda function is created using the uploaded code from the S3 bucket. It references the IAM role for execution.
- **IAM Role**: An IAM role is created with the necessary permissions for Lambda to execute the function.
- **IAM Policy Attachment**: The Lambda basic execution role is attached to the IAM role.

This configuration ensures that the Lambda function is deployed with the specified code and dependencies.

