resource "aws_sagemaker_model" "kmeans_model" {
  name = "kmeans_model"
  instance_type = var.sagemaker_instance_type
  role_arn = aws_iam_role.kmeans_role.arn
  container_details = jsonencode([
    {
      image = aws_sagemaker_model_package.kmeans_model_package.model_data_url
      environment = {
        "SCIKIT_LEARN_VERSION": "0.24.2"
      }
    }
  ])
}

