  name = "kmeans_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AmazonSageMakerFullAccess"
  ]
}

resource "aws_sagemaker_infrastructure_configuration" "kmeans_infrastructure_configuration" {
  name = "kmeans_infrastructure_configuration"

  instance_type = var.sagemaker_instance_type
  subnet_ids = [aws_subnet.kmeans_subnet.id]
  security_group_ids = [aws_security_group.kmeans_security_group.id]

  volume_configuration = jsonencode({
    volume_size_in_gb = 50
    volume_type = "gp2"
  })
}

resource "aws_subnet" "kmeans_subnet" {
  vpc_id = aws_vpc.kmeans_vpc.id
  cidr_block = "10.0.1.0/24"
}

resource "aws_security_group" "kmeans_security_group" {
  name = "kmeans_security_group"
  vpc_id = aws_vpc.kmeans_vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_vpc" "kmeans_vpc" {
  cidr_block = "10.0.0.0/16"
}
