```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

data "aws_ami" "latest_amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]
  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-x86_64-gp2-*"]
  }
}

resource "aws_launch_template" "amazon_linux_2_launch_template" {
  name_prefix = "amazon_linux_2_"

  image_id = data.aws_ami.latest_amazon_linux_2.id
  instance_type = "t2.micro"

  vpc_security_group_ids = [aws_security_group.example.id]

  user_data = <<-EOF
    #!/bin/bash
    echo "Hello, World!" > /tmp/hello.txt
    EOF

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  tags = {
    Name = "Amazon Linux 2 Launch Template"
  }
}

resource "aws_security_group" "example" {
  name        = "example_sg"
  description = "Example security group"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "Example Security Group"
  }
}

resource "aws_instance" "amazon_linux_2_instance" {
  ami           = aws_launch_template.amazon_linux_2_launch_template.image_id
  instance_type = aws_launch_template.amazon_linux_2_launch_template.instance_type
  subnet_id     = aws_subnet.example.id

  depends_on = [aws_launch_template.amazon_linux_2_launch_template]

  tags = {
    Name = "Amazon Linux 2 Instance"
  }
}

resource "aws_subnet" "example" {
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1a"

  tags = {
    Name = "Example Subnet"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **Data Source**: `aws_ami.latest_amazon_linux_2` retrieves the latest Amazon Linux 2 AMI.
- **Launch Template**: `aws_launch_template.amazon_linux_2_launch_template` defines the instance type, AMI ID, and security group.
- **Security Group**: `aws_security_group.example` allows SSH access and allows all outbound traffic.
- **Subnet**: `aws_subnet.example` specifies the subnet where the instance will be launched.
- **Instance**: `aws_instance.amazon_linux_2_instance` uses the launch template and is dependent on the launch template resource.

