  security_groups   = [aws_security_group.ec2_fleet_sg.id]
  iam_instance_profile = aws_iam_instance_profile.ec2_fleet_instance_profile.name
  user_data         = <<-EOF
    #!/bin/bash
    yum update -y
    EOF
}

resource "aws_security_group" "ec2_fleet_sg" {
  name        = "ec2_fleet_sg"
  description = "Security group for EC2 Fleet"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "ec2_fleet_role" {
  name = "ec2_fleet_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ec2_fleet_instance_profile" {
  name = "ec2_fleet_instance_profile"
  role = aws_iam_role.ec2_fleet_role.name
}

resource "aws_iam_policy" "ec2_fleet_policy" {
  name = "ec2_fleet_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:RunInstances",
          "ec2:TerminateInstances",
          "ec2:DescribeInstances",
          "ec2:DescribeSpotInstanceRequests",
          "ec2:DescribeSpotInstanceFleets"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "ec2_fleet_policy_attachment" {
  name       = "ec2_fleet_policy_attachment"
  policy_arn = aws_iam_policy.ec2_fleet_policy.arn
  roles      = [aws_iam_role.ec2_fleet_role.name]
}

resource "aws_ec2_fleet" "ec2_fleet" {
  launch_template_specification {
    launch_template_id = aws_launch_template.linux_2_launch_template.id
  }

  target_capacity_specification {
    total_target_capacity = 9
    on_demand_target_capacity = 5
    spot_target_capacity = 4
  }

  subnet_mappings {
    subnet_id = aws_subnet.public_subnet.id
  }

  subnet_mappings {
    subnet_id = aws_subnet.private_subnet.id
  }
}
