```hcl
provider "aws" {
  region = "us-east-1"
}

variable "msk_cluster_name" {
  default = "msk-cluster"
}

variable "msk_cluster_size" {
  default = 3
}

variable "msk_cluster_version" {
  default = "2.8.0"
}

variable "msk_logs_bucket_name" {
  default = "msk-logs-bucket"
}

resource "aws_iam_role" "msk_cluster_iam_role" {
  name = "${var.msk_cluster_name}_iam_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_cluster_iam_role_policy_attachment" {
  role       = aws_iam_role.msk_cluster_iam_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMQFullAccess"
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "msk_subnet" {
  count           = var.msk_cluster_size
  cidr_block      = cidrsubnet(aws_vpc.msk_vpc.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  vpc_id          = aws_vpc.msk_vpc.id
}

resource "aws_security_group" "msk_security_group" {
  name        = "${var.msk_cluster_name}_security_group"
  description = "Security group for MSK cluster"

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = var.msk_logs_bucket_name
  acl    = "private"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = var.msk_cluster_name
  kafka_version = var.msk_cluster_version
  number_of_broker_nodes = var.msk_cluster_size
  broker_node_group_info {
    instance_type = "m5.large"
    instance_count = var.msk_cluster_size
    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
    security_groups = [aws_security_group.msk_security_group.id]
  }
  logging_configuration {
    broker_logs {
      cloudwatch_logs {
        enabled = true
        log_group = "/aws/msk/${var.msk_cluster_name}"
      }
    }
  }
  tags = {
    Name = var.msk_cluster_name
  }
}

resource "aws_msk_cluster_logging_configuration" "msk_cluster_logging_configuration" {
  cluster_name = aws_msk_cluster.msk_cluster.cluster_name
  s3_logs {
    bucket = aws_s3_bucket.msk_logs_bucket.bucket
    prefix = "logs/"
  }
}
```

