provider "aws" {
  region = "us-west-2"
}

variable "msk_cluster_name" {
  default = "msk-cluster"
}

variable "msk_cluster_size" {
  default = 3
}

resource "aws_iam_role" "msk_cluster_role" {
  name = "${var.msk_cluster_name}_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_cluster_policy" {
  name = "${var.msk_cluster_name}_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kafka:*"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kafka" "msk_cluster" {
  name              = var.msk_cluster_name
  number_of_brokers = var.msk_cluster_size
  broker_node_group_info {
    instance_type = "m5.large"
    client_subnets = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]
    security_groups = ["sg-12345678"]
  }

  depends_on = [aws_iam_role.msk_cluster_role]
}

resource "aws_kafka_broker" "msk_broker_1" {
  depends_on = [aws_kafka.msk_cluster]
}

resource "aws_kafka_broker" "msk_broker_2" {
  depends_on = [aws_kafka.msk_cluster]
}

resource "aws_kafka_broker" "msk_broker_3" {
  depends_on = [aws_kafka.msk_cluster]
}
