resource "aws_iam_policy" "msk_broker_policy" {
  name = "${var.msk_cluster_name}_broker_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kafka:*",
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_broker_role_policy_attachment" {
  role       = aws_iam_role.msk_broker_role.name
  policy_arn = aws_iam_policy.msk_broker_policy.arn
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = var.msk_cluster_name
  kafka_version = "2.8.1"
  number_of_broker_nodes = var.msk_broker_count

  broker_node_group_info {
    instance_type = "m5.large"
    broker_azs     = ["us-east-1a", "us-east-1b", "us-east-1c"]
  }

  encryption_info {
    encryption_at_rest {
      data_volume_kms_key_id = aws_kms_key.msk_cluster.key_id
    }
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
      inter_broker = "TLS_PLAINTEXT"
    }
  }

  tags = {
    Name = var.msk_cluster_name
  }
}

resource "aws_kms_key" "msk_cluster" {
  description = "KMS key for MSK cluster encryption"
}
```

