variable "msk_cluster_encryption_at_rest" {
  default = true
}

variable "msk_cluster_open_monitoring" {
  default = true
}

variable "msk_connect_config_bucket_name" {
  default = "my-msk-connect-config-bucket"
}

variable "msk_connect_delivery_stream_name" {
  default = "my-msk-connect-delivery-stream"
}

variable "debezium_plugin_zip_url" {
  default = "https://repo1.maven.org/maven2/io/debezium/debezium-connector-postgres/1.9.8.Final/debezium-connector-postgres-1.9.8.Final.zip"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = var.msk_cluster_name
  number_of_broker_nodes = var.msk_cluster_broker_count
  encryption_at_rest {
    client_authentication = "DISABLED"
    storage_encryption {
      provider = "SOFTWARE"
    }
  }
  monitoring {
    enhanced_monitoring = var.msk_cluster_open_monitoring ? "DEFAULT" : "DISABLED"
  }
  tags = {
    Name = var.msk_cluster_name
  }
}

resource "aws_cloudwatch_log_group" "msk_logs" {
  name = "${var.msk_cluster_name}_logs"
}

resource "aws_s3_bucket" "msk_connect_config" {
  bucket = var.msk_connect_config_bucket_name
  acl = "private"
  versioning {
    enabled = true
  }
  lifecycle_rule {
    id     = "delete-old-versions"
    prefix = ""
    status = "Enabled"
    expiration {
      days = 30
    }
  }
}

resource "aws_kinesis_firehose_delivery_stream" "msk_connect_delivery_stream" {
  name = var.msk_connect_delivery_stream_name
  destination {
    s3 {
      bucket_arn = aws_s3_bucket.msk_connect_config.arn
      role_arn   = aws_iam_role.msk_connect_delivery_stream_role.arn
    }
  }
  tags = {
    Name = var.msk_connect_delivery_stream_name
  }
}

