  role       = aws_iam_role.msk_connect_delivery_stream_role.name
}

resource "aws_msk_connect_custom_plugin" "debezium_plugin" {
  name        = "debezium_plugin"
  zip_file_url = var.debezium_plugin_zip_url
  description = "Debezium PostgreSQL connector"
  tags = {
    Name = "debezium_plugin"
  }
