```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the Neptune cluster and instance will be deployed."
  type        = string
  default     = "vpc-12345678"
}

variable "subnet_id" {
  description = "The ID of the subnet where the Neptune instance will be deployed."
  type        = string
  default     = "subnet-87654321"
}

variable "neptune_cluster_name" {
  description = "The name of the Neptune cluster."
  type        = string
  default     = "neptune-cluster"
}

variable "neptune_instance_name" {
  description = "The name of the Neptune instance."
  type        = string
  default     = "neptune-instance"
}

variable "neptune_parameter_group_name" {
  description = "The name of the Neptune parameter group."
  type        = string
  default     = "neptune-parameter-group"
}

resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier          = var.neptune_cluster_name
  availability_zones         = ["us-west-2a", "us-west-2b"]
  db_subnet_group_name       = aws_neptune_subnet_group.neptune_subnet_group.name
  engine                     = "neptune"
  engine_version             = "1.2.0"
  master_username            = "admin"
  master_password            = "password123"
  skip_final_snapshot         = true
  preferred_backup_window     = "03:00-04:00"
  preferred_maintenance_window = "02:00-03:00"
}

resource "aws_neptune_subnet_group" "neptune_subnet_group" {
  name                   = var.neptune_parameter_group_name
  subnet_ids              = [var.subnet_id]
  description            = "Subnet group for Neptune cluster"
}

resource "aws_neptune_parameter_group" "neptune_parameter_group" {
  name           = var.neptune_parameter_group_name
  family         = "neptune1"
  description    = "Custom Neptune parameter group"
  parameters = {
    max_allocated_storage = "200"
    min_allocated_storage = "50"
    max_connections      = "100"
    max_user_connections = "50"
  }
}

resource "aws_security_group" "neptune_sg" {
  name        = "${var.neptune_instance_name}_sg"
  description = "Security group for Neptune instance"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_network_acl" "neptune_nacl" {
  vpc_id = var.vpc_id
  name   = "${var.neptune_instance_name}_nacl"
}

resource "aws_network_acl_entry" "neptune_nacl_inbound" {
  network_acl_id = aws_network_acl.neptune_nacl.id
  rule_number    = 100
  protocol       = "-1"
  cidr_block     = "0.0.0.0/0"
  action         = "allow"
}

resource "aws_network_acl_entry" "neptune_nacl_outbound" {
  network_acl_id = aws_network_acl.neptune_nacl.id
  rule_number    = 100
  protocol       = "-1"
  cidr_block     = "0.0.0.0/0"
  action         = "allow"
}

resource "aws_route_table" "neptune_rt" {
  vpc_id = var.vpc_id
  name   = "${var.neptune_instance_name}_rt"
}

resource "aws_route" "neptune_route" {
  route_table_id = aws_route_table.neptune_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id          = aws_internet_gateway.internet_gateway.id
}

resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = var.vpc_id
  name   = "${var.neptune_instance_name}_igw"
}

resource "aws_neptune_instance" "neptune_instance" {
  identifier            = var.neptune_instance_name
  cluster_identifier     = aws_neptune_cluster.neptune_cluster.cluster_identifier
  instance_class         = "db.r5.large"
  engine                 = "neptune"
  engine_version         = "1.2.0"
  parameter_group_name   = aws_neptune_parameter_group.neptune_parameter_group.name
  subnet_id              = var.subnet_id
  publicly_accessible    = false
  tags = {
    Name = var.neptune_instance_name
  }
}
```

