  })

  policies = [
    jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = [
            "s3:GetObjectVersion",
            "s3:ListBucketVersions"
          ]
          Resource = [
            "${aws_s3_bucket.source_bucket.arn}/*"
          ]
        },
        {
          Effect   = "Allow"
          Action   = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents"
          ]
          Resource = [
            "${aws_logs_log_group.lambda_execution_role_logs.arn}"
          ]
        }
      ]
    })
  ]
}

resource "aws_logs_log_group" "lambda_execution_role_logs" {
  name = "/aws/lambda/${aws_lambda_function.generate_inventory_report.function_name}"
}
