provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet" {
  vpc_id     = aws_vpc.vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_security_group" "security_group" {
  name        = "autograder_sg"
  description = "Allow SSH and HTTP/HTTPS access"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "autograder_instance" {
  ami           = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI
  instance_type = "t2.micro"
  key_name       = "your_key_pair_name" # Replace with your existing key pair name
  vpc_security_groups = [aws_security_group.security_group.id]
  subnet_id        = aws_subnet.subnet.id
  user_data = <<-EOF
    #!/bin/bash
    sudo yum update -y
    sudo yum install -y git
    EOF
}

resource "aws_s3_bucket" "code_bucket" {
  bucket = "autograder-code-bucket"
  acl    = "private"
}

resource "aws_codebuild_project" "codebuild_project" {
  name          = "autograder_codebuild"
  description = "Build and run student code"
  source {
    type        = "GitHub"
    location    = "https://github.com/your-repo-url.git" # Replace with your repository URL
    branch_name = "main"
  }
  artifacts {
    type        = "S3"
    location    = aws_s3_bucket.code_bucket.bucket
    packaging   = "ZIP"
  }
  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image         = "aws/codebuild/standard:5.0"
    privileged_mode = true
  }
  service_role = aws_iam_role.codebuild_service_role.arn
}

resource "aws_iam_role" "codebuild_service_role" {
  name = "codebuild-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_service_role_policy" {
  role       = aws_iam_role.codebuild_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildServiceRolePolicy"
}
