    privileged_mode = true
  }
  service_role = aws_iam_role.autograder_service_role.arn
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_vpc_subnet" "subnet" {
  vpc_id     = aws_vpc.vpc.id
  cidr_block = "10.0.1.0/24"
}

resource "aws_security_group" "security_group" {
  name        = "autograder-security-group-${var.environment}"
  description = "Security group for the autograding process."

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "autograder_service_role" {
  name = "autograder-service-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "autograder_service_role_policy_attachment" {
  role       = aws_iam_role.autograder_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildServiceRolePolicy"
}

variable "environment" {
  description = "The environment for the autograding process."
  default     = "dev"
}

variable "github_repository_url" {
  description = "The URL of the GitHub repository containing the students' code."
  default     = "https://github.com/example/cs-class-autograder.git"
}
