provider "aws" {
  region = "us-east-1" # Specify your desired AWS region
}

resource "aws_s3_bucket" "lambda_function_zip" {
  bucket = "lambda-function-zip-${var.environment}"
  acl    = "private"
}

resource "aws_s3_object" "lambda_function_zip_file" {
  bucket = aws_s3_bucket.lambda_function_zip.bucket
  key    = "lambda_func.zip"
  source = "./supplement/lambda_func.zip"
}

resource "aws_lambda_function" "lambda_function" {
  function_name = "lambda_function_${var.environment}"
  role          = aws_iam_role.lambda_function_execution.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  memory_size   = 128
  timeout       = 60

  zip_file = filebase64(aws_s3_object.lambda_function_zip_file.source)
}

resource "aws_iam_role" "lambda_function_execution" {
  name = "lambda_function_execution_${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_function_execution_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_function_execution.name
}

resource "aws_eventbridge_rule" "cron_rule" {
  name        = "cron_rule_${var.environment}"
  schedule_expression = "cron(0 7 * * ? *)"

  targets = [
    {
      arn = aws_lambda_function.lambda_function.arn
    }
  ]
}

variable "environment" {
  description = "Environment identifier for naming resources"
  type        = string
  default     = "dev"
}
