provider "aws" {
  region = "us-east-1" # Choose your desired AWS region
}

variable "bucket_name" {
  default = "video-streaming-bucket"
}

variable "distribution_domain_name" {
  default = "example.com"
}

resource "aws_s3_bucket" "video_streaming_bucket" {
  bucket = var.bucket_name

  acl = "public-read"

  website {
    index_document = "index.html"
    error_document = "error.html"
  }

  tags = {
    Name = "Video Streaming Bucket"
  }
}

resource "aws_s3_bucket_policy" "allow_public_access" {
  bucket = aws_s3_bucket.video_streaming_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = "*"
        Action = [
          "s3:GetObject"
        ]
        Resource = "${aws_s3_bucket.video_streaming_bucket.arn}/*"
      }
    ]
  })
}

resource "aws_cloudfront_origin_access_identity" "cloudfront_oai" {
  comment = "CloudFront Origin Access Identity"
}

resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  origin {
    domain_name = aws_s3_bucket.video_streaming_bucket.bucket_regional_domain_name
    origin_id   = "S3Origin-${aws_s3_bucket.video_streaming_bucket.id}"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.cloudfront_oai.cloudfront_access_identity_path
    }
  }

  enabled             = true
  default_cache_behavior {
    allowed_methods   = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3Origin-${aws_s3_bucket.video_streaming_bucket.id}"
    viewer_protocol_policy = "allow-all"
  }

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations       = ["US", "CA", "GB", "AU"]
    }
  }

  custom_error_response {
    error_code           = 403
    response_page_path = "/error.html"
    response_http_status = 200
  }

  logging_config {
    bucket = "my-logging-bucket.s3.amazonaws.com"
    prefix = "logs/"
  }

  tags = {
    Name = "Video Streaming Distribution"
  }
}

output "distribution_domain_name" {
  value = aws_cloudfront_distribution.video_streaming_distribution.domain_name
}
