provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "The domain name for the video streaming site"
  default     = "example.com"
}

resource "aws_s3_bucket" "video_content_bucket" {
  bucket = "${var.domain_name}"
  acl    = "public-read"
}

resource "aws_s3_bucket_website" "video_content_website" {
  bucket = aws_s3_bucket.video_content_bucket.bucket
  index_document {
    suffix = "index.html"
  }
}

resource "aws_route53_zone" "video_streaming_site_zone" {
  name = "${var.domain_name}"
}

resource "aws_route53_record" "video_streaming_site_cname" {
  zone_id = aws_route53_zone.video_streaming_site_zone.zone_id
  name    = var.domain_name
  type    = "CNAME"
  ttl     = 300
  records = [aws_cloudfront_distribution.video_streaming_site_distribution.domain_name]
}

resource "aws_cloudfront_distribution" "video_streaming_site_distribution" {
  origin {
    s3_origin_config {
      s3_bucket_source_domain_name = aws_s3_bucket.video_content_bucket.bucket_domain_name
    }
  }

  default_cache_behavior {
    target_origin_id = aws_s3_bucket.origin[0].id
    viewer_protocol_policy = "allow-all"
    allowed_methods = ["GET", "HEAD"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
    min_ttl = 0
    default_ttl = 3600
    max_ttl = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations = ["US", "CA", "UK", "DE"]
    }
  }

  enabled = true
}
