  region = "us-west-2"
}

variable "db_instance_name" {
  default = "my_postgres_db"
}

variable "db_instance_engine_version" {
  default = "13.6"
}

variable "db_instance_instance_class" {
  default = "db.t2.micro"
}

variable "db_instance_allocated_storage" {
  default = 20
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet" {
  vpc_id     = aws_vpc.vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "security_group" {
  name        = "postgres_sg"
  description = "Allow inbound traffic on port 5432"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "db_instance" {
  allocated_storage  = var.db_instance_allocated_storage
  engine            = "postgres"
  engine_version    = var.db_instance_engine_version
  instance_class     = var.db_instance_instance_class
  db_name           = var.db_instance_name
  username          = "admin"
  password          = "securepassword123"
  vpc_security_groups = [aws_security_group.security_group.id]
  subnet_ids         = [aws_subnet.subnet.id]
  publicly_accessible = false
}
```

