```hcl
provider "aws" {
  region = "us-west-2"
}

variable "iam_role_arn" {
  description = "ARN of the IAM role for SQLSERVER_AUDIT"
  default     = ""
}

variable "s3_bucket_arn" {
  description = "ARN of the S3 bucket for SQLSERVER_AUDIT"
  default     = ""
}

resource "aws_rds_option_group" "option_group_pike" {
  name        = "option_group_pike"
  major_engine_version = "11"
  engine_name   = "sqlserver-ee"

  option {
    name           = "SQLSERVER_AUDIT"
    option_settings = {
      "AuditTargetArn" = var.iam_role_arn
    }
  }

  option {
    name = "TDE"
  }
}

resource "aws_iam_role" "iam_role_pike" {
  name = "iam_role_pike"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "iam_policy_pike" {
  name = "iam_policy_pike"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = var.s3_bucket_arn
      }
    ]
  })
}

resource "aws_s3_bucket" "s3_bucket_pike" {
  bucket = "pike-s3-bucket"
}
```

