provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

resource "aws_iam_role" "lightsail_db_instance_role" {
  name = "lightsail_db_instance_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lightsail_db_instance_policy_attachment" {
  role       = aws_iam_role.lightsail_db_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/LightsailDefaultServiceRole"
}

resource "aws_lightsail_instance" "lightsail_mysql_instance" {
  name              = "lightsail_mysql_instance"
  availability_zone = "us-east-1a"  # Specify your desired Availability Zone
  blueprint_id      = "ubuntu_22_04"
  bundle_id         = "nano_1_0"

  tags = {
    Name = "lightsail_mysql_instance"
  }

  depends_on = [aws_iam_role.lightsail_db_instance_role]
}

resource "aws_lightsail_database" "lightsail_mysql_database" {
  name             = "lightsail_mysql_database"
  instance_name   = aws_lightsail_instance.lightsail_mysql_instance.name
  engine           = "mysql"
  engine_version   = "8.0.28"
  username         = "admin"
  password         = "SecurePassword123!"
  master_username = "admin"
  master_password = "SecurePassword123!"

  tags = {
    Name = "lightsail_mysql_database"
  }

  depends_on = [aws_lightsail_instance.lightsail_mysql_instance]
}

resource "aws_lightsail_backup_schedule" "lightsail_mysql_backup_schedule" {
  instance_name = aws_lightsail_instance.lightsail_mysql_instance.name
  backup_time  = "16:00"
  backup_days  = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]
  backup_retention_count = 7

  depends_on = [aws_lightsail_database.lightsail_mysql_database]
}

resource "aws_lightsail_maintenance_window" "lightsail_mysql_maintenance_window" {
  instance_name = aws_lightsail_instance.lightsail_mysql_instance.name
  start_time    = "17:00"
  end_time      = "17:30"
  days_of_week  = ["tuesday"]

  depends_on = [aws_lightsail_database.lightsail_mysql_database]
}
