provider "aws" {
  region = "us-west-2" # Specify your desired AWS region
}

variable "glacier_vault_name" {
  description = "Name of the S3 Glacier vault"
  default     = "my_glacier_vault"
}

resource "aws_s3 Glacier_vault" "glacier_vault" {
  name = var.glacier_vault_name
}

resource "aws_s3 Glacier_vault_notification" "glacier_vault_notification" {
  vault_name = aws_s3 Glacier_vault.glacier_vault.name

  events = [
    "ArchiveRetrievalCompleted"
  ]

  sns_topic_arn = aws_sns_topic.glacier_vault_notification_topic.arn
}

resource "aws_sns_topic" "glacier_vault_notification_topic" {
  name = "${var.glacier_vault_name}_notification_topic"
}
