provider "aws" {
  region = "us-east-1"
}

variable "cognito_user_pool_name" {
  default = "example_user_pool"
}

variable "cognito_user_pool_client_name" {
  default = "example_user_pool_client"
}

resource "aws_cognito_user_pool" "example_user_pool" {
  name = var.cognito_user_pool_name
}

resource "aws_cognito_user_pool_client" "example_user_pool_client" {
  name          = var.cognito_user_pool_client_name
  user_pool_id = aws_cognito_user_pool.example_user_pool.id
  generate_secret = true
  allowed_oauth_flows = ["code", "implicit"]
  allowed_oauth_scopes = ["openid", "email", "profile"]
}

resource "aws_cognito_user_pool_domain" "example_user_pool_domain" {
  domain   = "${var.cognito_user_pool_name}.auth.us-east-1.amazoncognito.com"
  user_pool_id = aws_cognito_user_pool.example_user_pool.id
}

resource "aws_lb" "example_load_balancer" {
  name               = "example_load_balancer"
  internal           = false
  subnets            = ["subnet-12345678", "subnet-23456789"] # Replace with your subnet IDs
  security_groups     = ["sg-12345678"] # Replace with your security group ID
  enable_deletion_protection = true
}

resource "aws_lb_listener" "example_listener" {
  load_balancer_arn = aws_lb.example_load_balancer.arn
  port              = 80
  protocol          = "HTTP"
}

resource "aws_lb_listener_rule" "example_listener_rule" {
  listener_arn = aws_lb_listener.example_listener.arn
  priority      = 1
  action {
    type = "authenticate-cognito"
    authenticate_cognito_config {
      user_pool_id = aws_cognito_user_pool.example_user_pool.id
      user_pool_client_id = aws_cognito_user_pool_client.example_user_pool_client.id
      session_cookie_name = "session_cookie"
      session_timeout_seconds = 3600
      authentication_request_extra_params = {
        "custom_param" = "value"
      }
      redirect_http_code = "302"
    }
  }
  condition {
    path_pattern {
      values = ["/"]
    }
  }
}
